insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('7d684909-e897-5f52-be2f-2045f63a9f65','82abe809-66f4-5fa2-a41a-cdee4008286c','freitext','Erklären Sie den grundlegenden Unterschied zwischen Thermoplasten und Duroplasten und nennen Sie zu jeder Gruppe ein Anwendungsbeispiel.',2,'entwurf',true,false,2,null,false,'PT-WS-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('7d684909-e897-5f52-be2f-2045f63a9f65','Thermoplaste bestehen aus unvernetzten, fadenförmigen Makromolekülen. Beim Erwärmen werden sie weich und lassen sich wiederholt umformen und schweißen, beim Abkühlen erstarren sie erneut. Duroplaste sind nach dem Aushärten engmaschig chemisch vernetzt. Sie lassen sich nicht mehr aufschmelzen, sondern zersetzen sich bei starker Erwärmung. Beispiel Thermoplast: PP-Gehäuse, PE-Rohr. Beispiel Duroplast: Steckergehäuse aus Phenolharz, Schaltertaste.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Beschreibt Thermoplaste als unvernetzt und wiederholt umformbar", "punkte": 1}, {"id": "k2", "beschreibung": "Beschreibt Duroplaste als vernetzt und nicht wieder aufschmelzbar", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt ein zutreffendes Thermoplast-Beispiel", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt ein zutreffendes Duroplast-Beispiel", "punkte": 1}], "akzeptierte_synonyme": ["nicht vernetzt", "linear aufgebaut", "engmaschig vernetzt", "ausgehärtet", "nicht schmelzbar"], "haeufige_fehler": ["Verwechslung mit Elastomeren", "Behauptung, Duroplaste seien schweißbar"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('87472c77-b245-57ef-aaa4-21b2c0f995ab','fd6e238a-8aa0-5dee-85a6-aa9c8db09969','freitext','Nennen Sie vier Angaben, die im Schriftfeld einer technischen Zeichnung enthalten sind.',1,'entwurf',true,false,2,null,false,'PT-TU-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('87472c77-b245-57ef-aaa4-21b2c0f995ab','Benennung des Teils, Zeichnungsnummer, Maßstab, Werkstoff, Datum und Name des Zeichners, Projektionsmethode, Allgemeintoleranzen, Firmenname, Blattnummer und Änderungsstand.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Erste zutreffende Angabe", "punkte": 1}, {"id": "k2", "beschreibung": "Zweite zutreffende Angabe", "punkte": 1}, {"id": "k3", "beschreibung": "Dritte zutreffende Angabe", "punkte": 1}, {"id": "k4", "beschreibung": "Vierte zutreffende Angabe", "punkte": 1}], "akzeptierte_synonyme": ["Teilebezeichnung", "Zeichnungsnr.", "Werkstoffangabe", "Änderungsindex"], "haeufige_fehler": ["Nennung von Maßen, die nicht im Schriftfeld stehen"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('fda2ea9a-6c69-58f0-9946-a1618e049ef9','68bb7fa9-25eb-5d11-81e3-a54444b61d9c','freitext','Beim Drehen wird die Schnittgeschwindigkeit erhöht. Erläutern Sie, welche Auswirkungen das auf Werkzeug und Bearbeitungszeit hat.',3,'entwurf',true,false,2,null,false,'PT-WZ-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('fda2ea9a-6c69-58f0-9946-a1618e049ef9','Mit steigender Schnittgeschwindigkeit steigt die Temperatur in der Schnittzone deutlich an. Der Verschleiß an Frei- und Spanfläche nimmt zu, die Standzeit des Werkzeugs sinkt. Gleichzeitig verkürzt sich die Hauptzeit, weil pro Zeiteinheit mehr Werkstoff abgetragen wird. Wirtschaftlich muss deshalb ein Kompromiss zwischen kurzer Bearbeitungszeit und akzeptablen Werkzeugkosten gefunden werden. Die Oberflächengüte kann sich bis zu einem gewissen Punkt verbessern.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Nennt den Temperaturanstieg in der Schnittzone", "punkte": 1}, {"id": "k2", "beschreibung": "Stellt fest, dass die Standzeit sinkt", "punkte": 1}, {"id": "k3", "beschreibung": "Stellt fest, dass die Bearbeitungszeit sinkt", "punkte": 1}, {"id": "k4", "beschreibung": "Erkennt den wirtschaftlichen Zielkonflikt", "punkte": 1}], "akzeptierte_synonyme": ["Werkzeuglebensdauer", "Hauptzeit", "Verschleiß nimmt zu"], "haeufige_fehler": ["Behauptung, die Standzeit steige mit der Schnittgeschwindigkeit"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('1fc9ca6e-d1fc-58b0-a857-73156d0e5325','bf9403c9-6a63-538b-9ec6-b0718f1a5e4c','freitext','Nennen Sie drei Messgrößen, die sich mit einem Messschieber ermitteln lassen, und erklären Sie, warum ein Messschieber für die Prüfung einer Passung nach IT7 in der Regel nicht ausreicht.',2,'entwurf',true,false,2,null,false,'PT-PR-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('1fc9ca6e-d1fc-58b0-a857-73156d0e5325','Mit dem Messschieber lassen sich Außenmaße, Innenmaße und Tiefenmaße bestimmen, teilweise auch Absätze. Für eine Toleranz nach IT7 ist die Ablesegenauigkeit des Messschiebers zu grob und die Messunsicherheit im Verhältnis zur zulässigen Toleranz zu groß. Für solche Passungen werden Bügelmessschrauben, Innenmessgeräte oder Grenzlehren eingesetzt.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Nennt Außenmaß", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt Innenmaß und Tiefenmaß", "punkte": 1}, {"id": "k3", "beschreibung": "Begründet mit zu grober Ablesegenauigkeit bzw. Messunsicherheit", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt ein geeigneteres Prüfmittel", "punkte": 1}], "akzeptierte_synonyme": ["Mikrometer", "Bügelmessschraube", "Grenzlehrdorn"], "haeufige_fehler": ["Behauptung, der Messschieber sei für alle Toleranzen ausreichend"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('358f54e4-f533-5c0c-8f63-c2772850fbd7','685b7af8-cc0a-5c3a-9417-fdc227bce46e','freitext','Nennen Sie vier der sechs Hauptgruppen der Fertigungsverfahren nach DIN 8580 und geben Sie zu jeder ein Beispiel an.',2,'entwurf',true,false,2,null,false,'PT-FT-F01') on conflict (id) do nothing;
insert into normen (id,nummer,status) values ('cfcb982f-47b4-5ae6-9bf6-237e88d009e2','DIN 8580','gueltig') on conflict (id) do nothing;
insert into frage_normen (frage_id,norm_id) values ('358f54e4-f533-5c0c-8f63-c2772850fbd7','cfcb982f-47b4-5ae6-9bf6-237e88d009e2') on conflict do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('358f54e4-f533-5c0c-8f63-c2772850fbd7','Urformen, Beispiel Gießen oder Spritzgießen. Umformen, Beispiel Biegen oder Tiefziehen. Trennen, Beispiel Drehen, Bohren oder Sägen. Fügen, Beispiel Schweißen oder Schrauben. Beschichten, Beispiel Lackieren oder Galvanisieren. Stoffeigenschaft ändern, Beispiel Härten oder Glühen.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Erste Hauptgruppe mit passendem Beispiel", "punkte": 1}, {"id": "k2", "beschreibung": "Zweite Hauptgruppe mit passendem Beispiel", "punkte": 1}, {"id": "k3", "beschreibung": "Dritte Hauptgruppe mit passendem Beispiel", "punkte": 1}, {"id": "k4", "beschreibung": "Vierte Hauptgruppe mit passendem Beispiel", "punkte": 1}], "akzeptierte_synonyme": ["Stoffeigenschaften ändern", "Zerspanen als Beispiel für Trennen"], "haeufige_fehler": ["Zuordnung von Schweißen zum Umformen"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('fe465353-aa55-5459-96e0-bd07259403e5','cc46107b-8fb6-542c-8005-3fd221d054d0','freitext','An einer Produktionsanlage soll ein Zylinder eine schwere Last exakt positionieren und dort auch unter Last stehen bleiben. Begründen Sie, ob Sie einen pneumatischen oder einen hydraulischen Antrieb wählen.',3,'entwurf',true,false,2,null,false,'PT-MA-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('fe465353-aa55-5459-96e0-bd07259403e5','Es ist ein hydraulischer Antrieb zu wählen. Hydrauliköl ist nahezu inkompressibel, dadurch bleibt die Position auch unter wechselnder Last stabil und es lassen sich mit kleinen Zylindern große Kräfte erzeugen. Druckluft dagegen lässt sich zusammendrücken, ein Pneumatikzylinder würde unter Last nachfedern und die Position nicht exakt halten. Nachteile der Hydraulik sind der höhere Wartungsaufwand, die Leckagegefahr und die geringere Geschwindigkeit.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Entscheidet sich für Hydraulik", "punkte": 1}, {"id": "k2", "beschreibung": "Begründet mit der Inkompressibilität des Öls", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt die hohe erreichbare Kraft", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt mindestens einen Nachteil der Hydraulik", "punkte": 1}], "akzeptierte_synonyme": ["Öl lässt sich nicht komprimieren", "Luft federt nach"], "haeufige_fehler": ["Wahl der Pneumatik mit Verweis auf Geschwindigkeit, ohne die Positioniergenauigkeit zu berücksichtigen"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('ee5abdfc-d21f-528b-bfb4-a564543dd6d6','453a2695-29fe-5daa-98f7-3b99a86b3763','freitext','Nennen und erläutern Sie die vier Grundmaßnahmen der Instandhaltung nach DIN 31051.',2,'entwurf',true,false,2,null,false,'PP-IH-F01') on conflict (id) do nothing;
insert into normen (id,nummer,status) values ('af4024cd-abda-57fc-b9de-5b81efd367f8','DIN 31051','gueltig') on conflict (id) do nothing;
insert into frage_normen (frage_id,norm_id) values ('ee5abdfc-d21f-528b-bfb4-a564543dd6d6','af4024cd-abda-57fc-b9de-5b81efd367f8') on conflict do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('ee5abdfc-d21f-528b-bfb4-a564543dd6d6','Wartung verzögert den Abbau des Abnutzungsvorrats, zum Beispiel durch Schmieren, Reinigen und Nachstellen. Inspektion stellt den Ist-Zustand fest und beurteilt ihn, ohne einzugreifen. Instandsetzung stellt den Sollzustand nach einem Fehler oder Ausfall wieder her. Verbesserung steigert die Zuverlässigkeit oder Instandhaltbarkeit durch technische oder organisatorische Änderungen, ohne die geforderte Funktion zu ändern.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Wartung genannt und zutreffend erläutert", "punkte": 1}, {"id": "k2", "beschreibung": "Inspektion genannt und zutreffend erläutert", "punkte": 1}, {"id": "k3", "beschreibung": "Instandsetzung genannt und zutreffend erläutert", "punkte": 1}, {"id": "k4", "beschreibung": "Verbesserung genannt und zutreffend erläutert", "punkte": 1}], "akzeptierte_synonyme": ["Abnutzungsvorrat erhalten", "Zustand beurteilen", "Sollzustand wiederherstellen"], "haeufige_fehler": ["Verwechslung von Wartung und Inspektion"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('7551f58c-fa1a-5ae0-b2c2-3de41044b60c','770eeb84-d9de-5b36-878a-b69b9024625f','freitext','Während der laufenden Serie überschreitet ein Stichprobenwert die obere Eingriffsgrenze der Qualitätsregelkarte. Beschreiben Sie Ihr Vorgehen.',3,'entwurf',true,false,2,null,false,'PP-QS-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('7551f58c-fa1a-5ae0-b2c2-3de41044b60c','Zuerst die Messung wiederholen, um einen Mess- oder Ablesefehler auszuschließen. Bestätigt sich der Wert, den Prozess anhalten oder korrigieren, damit kein weiterer Ausschuss entsteht. Anschließend die seit der letzten in Ordnung befundenen Stichprobe gefertigten Teile sperren und prüfen. Die Ursache ermitteln, zum Beispiel Werkzeugverschleiß, Temperaturdrift oder falsche Einstellung, und beseitigen. Vorgang und Maßnahme dokumentieren, danach die Fertigung wieder freigeben und die Wirksamkeit überwachen. Vorgesetzten und Qualitätssicherung informieren.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Messung überprüfen bzw. Prozess anhalten", "punkte": 1}, {"id": "k2", "beschreibung": "Bereits gefertigte Teile sperren und prüfen", "punkte": 1}, {"id": "k3", "beschreibung": "Ursache ermitteln und beseitigen", "punkte": 1}, {"id": "k4", "beschreibung": "Dokumentation und Information der Verantwortlichen", "punkte": 1}], "akzeptierte_synonyme": ["Rückverfolgung", "Sperrlager", "Vorgesetzten informieren"], "haeufige_fehler": ["Weiterproduzieren, weil die Toleranzgrenze noch nicht erreicht ist"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('775bacf2-016f-56ff-b7e4-14490bc662e5','f07f3f33-4723-5303-9f35-62eae72f9d3c','freitext','Welche Angaben sollte ein Schichtübergabeprotokoll mindestens enthalten? Nennen Sie vier Punkte.',2,'entwurf',true,false,2,null,false,'PP-UP-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('775bacf2-016f-56ff-b7e4-14490bc662e5','Auftrags- und Stückzahlstand sowie erreichter Fertigungsfortschritt. Aufgetretene Störungen und die dagegen ergriffenen Maßnahmen. Zustand von Maschine, Werkzeugen und Prüfmitteln einschließlich Auffälligkeiten. Bestand an Material und Hilfsstoffen sowie offene Punkte für die Folgeschicht. Qualitätsauffälligkeiten und gesperrte Teile. Datum, Schicht sowie Namen der übergebenden und übernehmenden Person.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Auftrags- bzw. Produktionsstand", "punkte": 1}, {"id": "k2", "beschreibung": "Störungen und Maßnahmen", "punkte": 1}, {"id": "k3", "beschreibung": "Zustand von Maschine, Werkzeug oder Material", "punkte": 1}, {"id": "k4", "beschreibung": "Offene Punkte bzw. Namen und Zeitpunkt der Übergabe", "punkte": 1}], "akzeptierte_synonyme": ["Restmenge", "Werkzeugstandzeit", "Qualitätsauffälligkeiten"], "haeufige_fehler": ["Nennung reiner Zeiterfassungsdaten"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('d328e4c8-48f7-562c-a2f0-82d2b8944c00','48e4275e-0308-5f66-b4ef-c25c1c96dd28','freitext','Sie sollen einen neuen Fertigungsauftrag an einer Ihnen bekannten Maschine vorbereiten. Beschreiben Sie die wesentlichen Arbeitsschritte bis zum Start der Serie.',2,'entwurf',true,false,2,null,false,'PP-AS-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('d328e4c8-48f7-562c-a2f0-82d2b8944c00','Technische Unterlagen prüfen, also Zeichnung, Arbeitsplan und Zeichnungsstand auf Vollständigkeit und Aktualität. Werkstoff und Hilfsstoffe bereitstellen und auf Kennzeichnung prüfen. Werkzeuge und Spannmittel auswählen, prüfen und rüsten. Maschinenparameter einstellen, Programm laden. Erstmuster fertigen und mit geeigneten Prüfmitteln gegen die Zeichnung prüfen. Erst nach Erstmusterfreigabe die Serie starten und laufend Stichproben nehmen. Sicherheitseinrichtungen vor dem Anlauf auf Funktion prüfen.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Technische Unterlagen und Material prüfen", "punkte": 1}, {"id": "k2", "beschreibung": "Werkzeuge und Spannmittel rüsten, Parameter einstellen", "punkte": 1}, {"id": "k3", "beschreibung": "Erstmuster fertigen und prüfen", "punkte": 1}, {"id": "k4", "beschreibung": "Freigabe abwarten, Sicherheitseinrichtungen prüfen bzw. Stichproben vorsehen", "punkte": 1}], "akzeptierte_synonyme": ["Erstteilprüfung", "Einrichten", "Anfahrteil"], "haeufige_fehler": ["Serienstart ohne Erstmusterprüfung"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('891493f2-33f6-5007-a7c5-2b81dff7644e','abc89841-8dec-5da1-b718-3cd9fbcd1338','freitext','Nennen Sie die fünf Zweige der gesetzlichen Sozialversicherung und geben Sie zu zweien davon je eine Leistung an.',2,'entwurf',true,false,2,null,false,'WISO-SV-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('891493f2-33f6-5007-a7c5-2b81dff7644e','Krankenversicherung, Pflegeversicherung, Rentenversicherung, Arbeitslosenversicherung und Unfallversicherung. Leistungen zum Beispiel: Die Krankenversicherung übernimmt Behandlungskosten und zahlt Krankengeld. Die Rentenversicherung zahlt Altersrente und Erwerbsminderungsrente. Die Arbeitslosenversicherung zahlt Arbeitslosengeld und finanziert Weiterbildung. Die Unfallversicherung leistet nach Arbeitsunfällen und Berufskrankheiten.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Mindestens drei Zweige korrekt genannt", "punkte": 1}, {"id": "k2", "beschreibung": "Alle fünf Zweige korrekt genannt", "punkte": 1}, {"id": "k3", "beschreibung": "Erste zutreffende Leistung genannt", "punkte": 1}, {"id": "k4", "beschreibung": "Zweite zutreffende Leistung genannt", "punkte": 1}], "akzeptierte_synonyme": ["gesetzliche Krankenversicherung", "GRV", "Berufsgenossenschaft"], "haeufige_fehler": ["Nennung privater Versicherungen wie Haftpflicht"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('be747830-5363-5ec9-aa77-b42a61dc265b','3502eec5-14fa-54ec-9a78-335a5f03cb6f','freitext','Nennen Sie drei Pflichten des Ausbildenden und drei Pflichten der Auszubildenden nach dem Berufsbildungsgesetz.',2,'entwurf',true,false,2,null,false,'WISO-BA-F01') on conflict (id) do nothing;
insert into normen (id,nummer,status) values ('4f8cf74d-ba40-575e-87e9-5fc55822a8d1','BBiG','gueltig') on conflict (id) do nothing;
insert into frage_normen (frage_id,norm_id) values ('be747830-5363-5ec9-aa77-b42a61dc265b','4f8cf74d-ba40-575e-87e9-5fc55822a8d1') on conflict do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('be747830-5363-5ec9-aa77-b42a61dc265b','Pflichten des Ausbildenden: Vermittlung der Fertigkeiten und Kenntnisse des Ausbildungsberufsbildes, kostenlose Bereitstellung der Ausbildungsmittel, Freistellung für Berufsschule und Prüfungen, Zahlung einer angemessenen Vergütung, Führen eines Ausbildungsnachweises ermöglichen, Ausstellen eines Zeugnisses. Pflichten der Auszubildenden: Lernpflicht und Bemühenspflicht, Teilnahme am Berufsschulunterricht und an Prüfungen, Weisungen folgen, Sorgfaltspflicht im Umgang mit Werkzeugen und Material, Führen des Berichtshefts, Betriebsgeheimnisse wahren, Krankmeldung.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Zwei zutreffende Pflichten des Ausbildenden", "punkte": 1}, {"id": "k2", "beschreibung": "Dritte zutreffende Pflicht des Ausbildenden", "punkte": 1}, {"id": "k3", "beschreibung": "Zwei zutreffende Pflichten der Auszubildenden", "punkte": 1}, {"id": "k4", "beschreibung": "Dritte zutreffende Pflicht der Auszubildenden", "punkte": 1}], "akzeptierte_synonyme": ["Berichtsheftpflicht", "Freistellungspflicht", "Vergütungspflicht"], "haeufige_fehler": ["Verwechslung der Pflichten beider Seiten"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('28e62b2d-92ac-5ea5-99a9-e7bf826925f9','c13e443a-816b-5f18-9887-9b90c4c329fa','freitext','An Ihrer Maschine entstehen ölhaltige Späne und verbrauchtes Putztuch. Erläutern Sie, wie Sie damit umgehen und begründen Sie Ihr Vorgehen.',2,'entwurf',true,false,2,null,false,'WISO-SU-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('28e62b2d-92ac-5ea5-99a9-e7bf826925f9','Ölhaltige Späne und ölgetränkte Putztücher sind gefährliche Abfälle und dürfen nicht in den Restmüll. Sie werden getrennt in gekennzeichnete, verschließbare Behälter gegeben, die dafür vorgesehen sind. Späne werden möglichst abgetropft oder abgeschleudert, damit das Öl zurückgewonnen und die Späne dem Recycling zugeführt werden können. Ölgetränkte Tücher sind zusätzlich selbstentzündungsgefährdet und gehören deshalb in einen Metallbehälter mit Deckel. Grundlage sind die Betriebsanweisung und die Abfallhierarchie mit Vorrang der Verwertung vor der Beseitigung.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Getrennte Sammlung in gekennzeichneten Behältern", "punkte": 1}, {"id": "k2", "beschreibung": "Erkennt die Einstufung als gefährlicher Abfall", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt Verwertung bzw. Ölrückgewinnung", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt die Brandgefahr bei ölgetränkten Tüchern oder verweist auf die Betriebsanweisung", "punkte": 1}], "akzeptierte_synonyme": ["Sonderabfall", "Wertstoff", "Selbstentzündung"], "haeufige_fehler": ["Entsorgung im Restmüll", "Vermischen mit nicht gefährlichem Abfall"]}'::jsonb,4) on conflict (frage_id) do nothing;
